fn native(line: &str) -> Result<Vec<u8>, String> {
    let inst = peacemaker_lift::text::parse_line(line, IrArch::Gfx1201)
        .map_err(|e| format!("{line}: parse: {e}"))?;
    let words = peacemaker_ir::codec::gfx12::encode(&inst).map_err(|e| format!("{line}: {e}"))?;
    Ok(words.iter().flat_map(|w| w.to_le_bytes()).collect())
}

#[test]
fn native_codec_matches_llvm_mc_golden() {
    let mut bad = Vec::new();
    for (line, want) in GOLDEN {
        match native(line) {
            Ok(got) if got == *want => {}
            Ok(got) => bad.push(format!("{line}: native {got:02x?} != llvm-mc {want:02x?}")),
            Err(e) => bad.push(e),
        }
    }
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}

fn words(bytes: &[u8]) -> Vec<u32> {
    bytes
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

/// Decoding the llvm-mc bytes and printing gives the canonical text llvm-objdump
/// prints, and parsing that text back re-encodes the same bytes.
#[test]
fn decode_print_round_trips_to_the_canonical_text() {
    let mut bad = Vec::new();
    for (line, bytes) in GOLDEN {
        let w = words(bytes);
        match peacemaker_ir::codec::gfx12::decode(&w) {
            Ok((inst, used)) if used == w.len() => {
                match peacemaker_lift::text::canonical(&inst, IrArch::Gfx1201) {
                    Ok(text) if text == *line => {}
                    Ok(text) => bad.push(format!("{line}: decode+print gave {text:?}")),
                    Err(e) => bad.push(format!("{line}: print: {e}")),
                }
            }
            Ok((_, used)) => bad.push(format!("{line}: decoded {used} of {} words", w.len())),
            Err(e) => bad.push(format!("{line}: decode: {e}")),
        }
    }
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}

const LLVM_MC: &str = "/opt/rocm/llvm/bin/llvm-mc";

fn run_mc(args: &[&str], input: &str) -> String {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut child = Command::new(LLVM_MC)
        .args(["-arch=amdgcn", "-mcpu=gfx1201"])
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn llvm-mc");
    child
        .stdin
        .take()
        .expect("llvm-mc stdin")
        .write_all(input.as_bytes())
        .expect("write llvm-mc stdin");
    let out = child.wait_with_output().expect("llvm-mc output");
    assert!(
        out.status.success(),
        "llvm-mc {args:?}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).expect("llvm-mc stdout is UTF-8")
}

/// With the pinned assembler installed, the GOLDEN bytes and canonical text are
/// re-derived live: assembling every line gives the recorded bytes and echoes the
/// line unchanged, and disassembling the bytes gives the line back.
#[test]
fn golden_agrees_with_installed_llvm_mc() {
    if !std::path::Path::new(LLVM_MC).is_file() {
        eprintln!("note: {LLVM_MC} not installed; skipping the live llvm-mc comparison");
        return;
    }
    let asm: String = GOLDEN.iter().map(|(line, _)| format!("{line}\n")).collect();
    let assembled = run_mc(&["-show-encoding"], &asm);
    let encoded: Vec<(String, Vec<u8>)> = assembled
        .lines()
        .filter_map(|l| l.split_once("; encoding: ["))
        .map(|(text, enc)| {
            let bytes = enc
                .trim_end_matches(']')
                .split(',')
                .map(|b| u8::from_str_radix(b.trim().trim_start_matches("0x"), 16).unwrap())
                .collect();
            (text.split_whitespace().collect::<Vec<_>>().join(" "), bytes)
        })
        .collect();
    assert_eq!(encoded.len(), GOLDEN.len(), "llvm-mc dropped a line");
    let mut bad = Vec::new();
    for ((line, bytes), (echo, mc_bytes)) in GOLDEN.iter().zip(&encoded) {
        if echo != line {
            bad.push(format!("{line}: llvm-mc echoes {echo:?}"));
        }
        if mc_bytes != bytes {
            bad.push(format!(
                "{line}: llvm-mc {mc_bytes:02x?} != GOLDEN {bytes:02x?}"
            ));
        }
    }
    let hex: String = GOLDEN
        .iter()
        .map(|(_, bytes)| {
            let b: Vec<String> = bytes.iter().map(|b| format!("{b:#04x}")).collect();
            format!("{}\n", b.join(" "))
        })
        .collect();
    let disassembled = run_mc(&["--disassemble"], &hex);
    let printed: Vec<String> = disassembled
        .lines()
        .map(|l| l.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|l| !l.is_empty() && !l.starts_with('.'))
        .collect();
    assert_eq!(printed.len(), GOLDEN.len(), "llvm-mc dropped a disassembly");
    for ((line, _), text) in GOLDEN.iter().zip(&printed) {
        if text != line {
            bad.push(format!("{line}: llvm-mc disassembles to {text:?}"));
        }
    }
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}
